import pandas as pd


def _sig_part(x):
    if pd.isna(x):
        return ''
    return str(x).rstrip()


def _sig(city, tier):
    return _sig_part(city) + '|' + _sig_part(tier)


def run(inputs: dict) -> dict:
    dim = inputs['DIM_MEMBER'].copy()
    stg = inputs['STG_MEMBER'].copy()

    # Work with a list of row-dicts so we can mutate/append freely while
    # preserving column order/dtypes as close as possible to the source.
    cols = list(dim.columns)
    rows = dim.to_dict('records')

    for _, s in stg.iterrows():
        member_id = s['member_id']
        s_city = s['city']
        s_tier = s['tier']
        update_date = s['update_date']

        # find current row for this member_id
        cur_idx = None
        for idx, r in enumerate(rows):
            if r.get('member_id') == member_id and r.get('is_current') == 1:
                cur_idx = idx
                break

        if cur_idx is None:
            new_row = {c: None for c in cols}
            new_row['member_id'] = member_id
            new_row['city'] = s_city
            new_row['tier'] = s_tier
            new_row['eff_start_date'] = update_date
            new_row['eff_end_date'] = None
            new_row['is_current'] = 1
            rows.append(new_row)
        else:
            c = rows[cur_idx]
            if _sig(s_city, s_tier) != _sig(c.get('city'), c.get('tier')):
                c['eff_end_date'] = update_date
                c['is_current'] = 0

                new_row = {col: None for col in cols}
                new_row['member_id'] = member_id
                new_row['city'] = s_city
                new_row['tier'] = s_tier
                new_row['eff_start_date'] = update_date
                new_row['eff_end_date'] = None
                new_row['is_current'] = 1
                rows.append(new_row)
            # else: no-op, keep c unchanged

    out = pd.DataFrame(rows, columns=cols)

    return {'dim_member_out': out}
